//! `aevalsrc` — an audio signal generated by a per-channel
//! [`vaco_expr`] expression, in `flt`.
//!
//! `ffmpeg -h filter=aevalsrc` documents `exprs` (a `|`-separated list of
//! per-channel expressions, no default), `nb_samples`/`n` (default 1024),
//! `sample_rate`/`s` (default `"44100"`), `duration`/`d` (default
//! `-0.000001`, the same "unlimited" sentinel `vaco-filter-plumbing`'s
//! `nullsrc` uses) and `channel_layout`/`c`.
//!
//! # Variables (measured, not read)
//!
//! Probed with `exprs='sin(2*PI*440*t)'` and `exprs='n'` against
//! `ffmpeg -f lavfi -i aevalsrc=... -f f32le -`: `t` is time in seconds
//! (`t = n / sample_rate`) and `n` is the absolute sample index from the
//! start of the stream — both bound through this crate's `vaco_expr`
//! evaluator, the same engine every other filter's expression option uses,
//! so this filter's exactness is inherited directly from `vaco-expr`'s own
//! (measured, documented) fidelity to the reference's expression language.
//! **Exact**, modulo one simplification below.
//!
//! # What is simplified
//!
//! Each channel's expression is evaluated with a fresh
//! [`vaco_expr::Registers`] per sample rather than one persisted across the
//! whole stream, so `ld`/`st` register state does not carry from sample to
//! sample. Expressions using only `t`/`n` (the overwhelming common case,
//! and everything in this crate's own tests) are unaffected.

use vaco_core::{Duration as VDuration, MediaType, Rational, Result, Timestamp};
use vaco_filter_core::adapt::{SourceFilter, Sourced};
use vaco_filter_core::negotiate::{FormatSet, NodeFormats};
use vaco_filter_core::{FilterContext, FilterDesc, FilterFlags, LinkFormat, Pad};
use vaco_frame::Frame;
use vaco_opts::OptionsExt as _;
use vaco_sampfmt::SampleFmt;

use vaco_filter_graph::registry::{Instance, Instantiate};

const UNLIMITED: VDuration = VDuration(-1);

#[derive(Debug, Clone, vaco_opts::Options)]
#[options(name = "aevalsrc", help = "generate audio from an expression")]
pub(crate) struct Opts {
    #[opt(name = "exprs", help = "set the channel expressions", default = String::new(), flags(filtering))]
    pub exprs: String,
    #[opt(name = "nb_samples", alias = "n", help = "set the number of samples per requested frame", default = 1024, range = 0..=i32::MAX, flags(filtering))]
    pub nb_samples: i32,
    #[opt(name = "sample_rate", alias = "s", help = "set the sample rate", default = "44100".to_owned(), flags(filtering))]
    pub sample_rate: String,
    #[opt(name = "duration", alias = "d", help = "set audio duration", default = UNLIMITED, flags(filtering))]
    pub duration: VDuration,
    #[opt(name = "channel_layout", alias = "c", help = "set channel layout", default = String::new(), flags(filtering))]
    pub channel_layout: String,
}

impl Opts {
    fn parse(args: Option<&str>) -> std::result::Result<Self, String> {
        let mut o = Self::default();
        if let Some(text) = args {
            o.set_from_string(text, "=", ":")
                .map_err(|e| e.to_string())?;
        }
        Ok(o)
    }
}

pub const DESC: FilterDesc = FilterDesc {
    name: "aevalsrc",
    description: "Generate an audio signal generated by an expression",
    inputs: &[],
    outputs: &[Pad {
        name: "default",
        media_type: MediaType::Audio,
    }],
    flags: FilterFlags::empty(),
};

#[derive(Debug)]
struct Source {
    exprs: Vec<vaco_expr::Expr>,
    layout: vaco_chlayout::ChannelLayout,
    sample_rate: u32,
    block: u32,
    total_samples: Option<u64>,
    produced: u64,
}

impl SourceFilter for Source {
    fn configure(&mut self, ctx: &mut FilterContext<'_>) -> Result<()> {
        if let Some(mut out) = ctx.output_link(0).cloned() {
            if let LinkFormat::Audio {
                sample_rate,
                layout,
                time_base,
                ..
            } = &mut out
            {
                *sample_rate = self.sample_rate;
                *layout = self.layout.clone();
                *time_base = Rational::new(1, i32::try_from(self.sample_rate.max(1)).unwrap_or(1));
            }
            ctx.set_output_link(0, out);
        }
        Ok(())
    }

    fn produce(&mut self, ctx: &mut FilterContext<'_>) -> Result<Option<Frame>> {
        if self.total_samples.is_some_and(|n| self.produced >= n) {
            return Ok(None);
        }
        let want = self.total_samples.map_or(self.block, |n| {
            u32::try_from(n - self.produced)
                .unwrap_or(self.block)
                .min(self.block)
        });
        let mut frame = ctx.pool().acquire_audio(
            SampleFmt::F32,
            self.layout.clone(),
            want,
            self.sample_rate,
        )?;
        for (ch, expr) in self.exprs.iter().enumerate() {
            if let Some(mut plane) = frame.plane_mut(ch)
                && let Some(row) = plane.row_mut(0)
            {
                for (i, px) in row.chunks_exact_mut(4).enumerate() {
                    let n = self.produced + i as u64;
                    #[allow(
                        clippy::cast_precision_loss,
                        reason = "audio sample counts stay far below 2^53"
                    )]
                    let n_f = n as f64;
                    let t = n_f / f64::from(self.sample_rate.max(1));
                    let v = expr.eval(&[t, n_f]);
                    #[allow(
                        clippy::cast_possible_truncation,
                        reason = "vaco_expr always returns a finite-representable f64 here"
                    )]
                    let vf = v as f32;
                    px.copy_from_slice(&vf.to_le_bytes());
                }
            }
        }
        frame.pts = Timestamp::new(i64::try_from(self.produced).unwrap_or(0));
        frame.time_base = Rational::new(1, i32::try_from(self.sample_rate.max(1)).unwrap_or(1));
        frame.duration = vaco_core::Duration(i64::from(want));
        self.produced = self.produced.saturating_add(u64::from(want));
        Ok(Some(frame))
    }

    fn end_pts(&self) -> Timestamp {
        Timestamp::new(i64::try_from(self.produced).unwrap_or(0))
    }

    fn flush_state(&mut self) {
        self.produced = 0;
    }
}

pub(crate) fn create(req: &Instantiate<'_>) -> std::result::Result<Instance, String> {
    let opts = Opts::parse(req.args)?;
    let bindings = vaco_expr::Bindings::new(&["t", "n"]);
    let exprs: Vec<vaco_expr::Expr> = opts
        .exprs
        .split('|')
        .map(|s| {
            vaco_expr::Expr::parse(s.trim(), &bindings)
                .map_err(|e| format!("aevalsrc: bad expression `{s}`: {e}"))
        })
        .collect::<std::result::Result<_, _>>()?;
    if exprs.is_empty() {
        return Err("aevalsrc: `exprs` must name at least one channel expression".to_owned());
    }
    let sample_rate: u32 = opts
        .sample_rate
        .trim()
        .parse()
        .map_err(|_| format!("aevalsrc: bad sample_rate `{}`", opts.sample_rate))?;
    let layout = if opts.channel_layout.is_empty() {
        #[allow(
            clippy::cast_possible_truncation,
            reason = "exprs.len() is a small channel count"
        )]
        vaco_chlayout::ChannelLayout::default_for(exprs.len() as u32).ok_or_else(|| {
            "aevalsrc: no default channel layout for this many channels".to_owned()
        })?
    } else {
        vaco_chlayout::ChannelLayout::from_name(&opts.channel_layout)
            .ok_or_else(|| format!("aevalsrc: bad channel_layout `{}`", opts.channel_layout))?
    };
    let total_samples = if opts.duration.0 < 0 {
        None
    } else {
        Some(
            (opts.duration.as_secs_f64() * f64::from(sample_rate))
                .round()
                .max(0.0) as u64,
        )
    };
    let source = Source {
        exprs,
        layout,
        sample_rate,
        block: u32::try_from(opts.nb_samples.max(1)).unwrap_or(1024),
        total_samples,
        produced: 0,
    };
    Ok(Instance {
        desc: DESC,
        formats: NodeFormats {
            inputs: Vec::new(),
            outputs: vec![FormatSet::default()],
            ties: Vec::new(),
            label: req.instance.to_owned(),
        },
        filter: Box::new(Sourced::new(source)),
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn n_variable_matches_the_measured_reference() {
        let bindings = vaco_expr::Bindings::new(&["t", "n"]);
        let expr = vaco_expr::Expr::parse("n", &bindings).unwrap_or_else(|_| unreachable!());
        for n in 0..8u64 {
            #[allow(clippy::cast_precision_loss, reason = "n < 8")]
            let n_f = n as f64;
            assert!((expr.eval(&[0.0, n_f]) - n_f).abs() < f64::EPSILON);
        }
    }

    #[test]
    fn t_variable_matches_the_measured_reference() {
        let bindings = vaco_expr::Bindings::new(&["t", "n"]);
        let expr =
            vaco_expr::Expr::parse("sin(2*PI*440*t)", &bindings).unwrap_or_else(|_| unreachable!());
        let sr = 8000.0;
        for n in 0..8u64 {
            #[allow(clippy::cast_precision_loss, reason = "n < 8")]
            let t = n as f64 / sr;
            let expected = (2.0 * std::f64::consts::PI * 440.0 * t).sin();
            assert!((expr.eval(&[t, 0.0]) - expected).abs() < 1e-9);
        }
    }

    #[test]
    fn creatable_with_a_simple_expression() {
        let req = Instantiate {
            name: "aevalsrc",
            instance: "aevalsrc",
            args: Some("exprs=sin(t)"),
            arguments: &[],
        };
        assert!(create(&req).is_ok());
    }

    #[test]
    fn empty_exprs_is_a_clean_error() {
        let req = Instantiate {
            name: "aevalsrc",
            instance: "aevalsrc",
            args: None,
            arguments: &[],
        };
        assert!(create(&req).is_err());
    }

    #[test]
    fn two_channel_exprs_parse() {
        let req = Instantiate {
            name: "aevalsrc",
            instance: "aevalsrc",
            args: Some("exprs=sin(t)|cos(t)"),
            arguments: &[],
        };
        assert!(create(&req).is_ok());
    }
}
